  },
  Item_49266_StoryDesc = {Text = "Inicio"},
  Item_49271_Desc = {
    Text = "Al adquirir el \"Tema principal\" en el \"Registro de temas\", se obtiene.\n\"No se les permite acercarse ni medio paso al Guardián...!\""
  },
  Item_49271_Name = {
    Text = "En nombre de la Llave de Plata: Ramona Circular"
  },
  Item_49271_StoryDesc = {
