  Item_50032_Name = {Text = "mandíbula"},
  Item_51105_Desc = {
    Text = "Obtenido al completar \"Misterio del guion\" o al lograr un logro en la actividad \"La magia de la historia·clon\", un objeto para intercambiar en la \"Tienda de guiones mágicos\".\nEl conocimiento es efímero, como una estrella fugaz que atraviesa el cielo nocturno. La diferencia es que tienes la manera de hacerlo perdurable."
  },
  Item_51105_Name = {
    Text = "Inspiración errante"
  },
  Item_51265_Desc = {
    Text = "Se obtiene al superar \"El laberinto del guion\" o completar los logros de la actividad en el evento \"La magia de la historia · Reedición\". Es un objeto utilizado para realizar intercambios en la \"Tienda del guion mágico\".\nEl Conocimiento es efímero, como una estrella fugaz que cruza el cielo nocturno. La diferencia es que tú tienes la manera de retenerlo para siempre.\n\nCae al menos {s1} unidad(es)"
  },
